1	/**
2	 * Wikilink linting — pure logic, no pi dependency.
3	 *
4	 * Convention enforced by the wikilink-lint extension:
5	 *   - File references in docs use wikilink syntax: [[path]]
6	 *   - Paths are relative to the docs/ directory (the "docs root")
7	 *   - Wikilinks may ONLY point to files inside docs/ (no code, no repo-external)
8	 *
9	 * This module is import-safe and unit-testable without the pi runtime.
10	 */
11	
12	import { existsSync, statSync } from "node:fs";
13	import { isAbsolute, relative, resolve, sep } from "node:path";
14	
15	export type WikilinkIssueKind = "out-of-docs" | "absolute" | "not-found";
16	
17	export interface WikilinkIssue {
18		/** The full wikilink as written, e.g. [[../src/index.ts]]. */
19		raw: string;
20		/** Extracted docs-relative file path, or "" when there is none. */
21		target: string;
22		kind: WikilinkIssueKind;
23	}
24	
25	/** Matches [[ ... ]]. Inner content may not contain brackets. */
26	const WIKILINK_RE = /\[\[([^\[\]]+?)\]\]/g;
27	
28	/**
29	 * Extract wikilink targets from markdown text.
30	 *
31	 * Handles aliases and anchors:
32	 *   [[a/b.md]]              -> a/b.md
33	 *   [[a/b.md|Alias]]        -> a/b.md   (alias after first |)
34	 *   [[a/b.md#Heading]]      -> a/b.md   (anchor after first #)
35	 *   [[a/b.md#H|Alias]]      -> a/b.md
36	 *   [[a/b.md\|Alias]]      -> a/b.md   (escaped \| inside a Markdown table cell)
37	 *   [[#Heading]]            -> ""        (same-file anchor, no file)
38	 */
39	export function extractWikilinkTargets(text: string): { raw: string; target: string }[] {
40		const out: { raw: string; target: string }[] = [];
41		for (const match of text.matchAll(WIKILINK_RE)) {
42			const raw = match[0];
43			const inner = match[1];
44			// Drop alias: the separator is "|", but inside Markdown table cells it is
45			// escaped as "\|". Split on either, take the part before it; then drop any
46			// anchor ("#heading").
47			const filePart = inner.split(/\\\||\|/)[0].split("#")[0].trim();
48			out.push({ raw, target: filePart });
49		}
50		return out;
51	}
52	
53	/**
54	 * Validate every wikilink in `text`.
55	 *
56	 * @param text     The (final) markdown content of a docs file.
57	 * @param docsRoot Absolute path to the docs/ directory. Wikilink paths are
58	 *                 resolved against this root.
59	 * @returns Issues for links that escape docs/, use absolute paths, or point
60	 *          to non-existent (or non-file) targets.
61	 */
62	export function lintLinks(text: string, docsRoot: string): WikilinkIssue[] {
63		const issues: WikilinkIssue[] = [];
64	
65		for (const { raw, target } of extractWikilinkTargets(text)) {
66			// [[#anchor]] and [[ |alias]] with no file -> nothing to validate.
67			if (target === "") continue;
68	
69			if (isAbsolute(target)) {
70				issues.push({ raw, target, kind: "absolute" });
71				continue;
72			}
73	
74			const abs = resolve(docsRoot, target);
75			const rel = relative(docsRoot, abs);
76	
77			// Escaped docs/ (or targets the docs root dir itself).
78			if (rel === "" || rel === ".." || rel.startsWith(`..${sep}`)) {
79				issues.push({ raw, target, kind: "out-of-docs" });
80				continue;
81			}
82	
83			// Must exist and be a regular file.
84			if (!existsSync(abs) || !statSync(abs).isFile()) {
85				issues.push({ raw, target, kind: "not-found" });
86			}
87		}
88	
89		return issues;
90	}
91	
92	/** Human-readable, LLM-facing message for a set of issues. */
93	export function describeIssues(issues: WikilinkIssue[]): string {
94		const lines = issues.map((issue) => {
95			const why =
96				issue.kind === "out-of-docs"
97					? "指向 docs/ 之外——wikilink 仅可引用文档库内的内容"
98					: issue.kind === "absolute"
99						? "使用了绝对路径——wikilink 必须相对 docs/"
100						: "目标文件不存在";
101			return `  • ${issue.raw} — ${why}`;
102		});
103	
104		return [
105			"wikilink-lint：以下 wikilink 不合规，已阻断写入：",
106			...lines,
107			"请先创建缺失文件、改为指向 docs/ 内已存在的文档，或对库外内容（如代码）改用普通文字 / 行内代码描述，然后重试。",
108		].join("\n");
109	}
