import { execFileSync, spawn } from "node:child_process";

export interface ExecCaptureResult {
  stdout: string;
  stderr: string;
  exitCode: number;
}

/** Return true only when both terminal streams are available and tty use is allowed. */
export function isInteractive(): boolean {
  return (
    process.stdin.isTTY === true &&
    process.stdout.isTTY === true &&
    !process.env.CI &&
    !process.env.PISQUAD_NO_TTY
  );
}

/** Find an executable using the host platform's command lookup utility. */
export function which(cmd: string): string | null {
  if (!cmd) return null;

  try {
    const lookup = process.platform === "win32" ? "where.exe" : "sh";
    const args = process.platform === "win32" ? [cmd] : ["-c", 'command -v "$1"', "pisquad-which", cmd];
    const output = execFileSync(lookup, args, {
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
    });
    const result = output.trim().split(/\r?\n/)[0];
    return result || null;
  } catch {
    return null;
  }
}

/** Execute a child process without a shell and capture all of its output. */
export function execCapture(cmd: string, args: string[] = []): Promise<ExecCaptureResult> {
  return new Promise((resolve) => {
    let stdout = "";
    let stderr = "";
    let settled = false;

    const finish = (exitCode: number): void => {
      if (settled) return;
      settled = true;
      resolve({ stdout, stderr, exitCode });
    };

    let child;
    try {
      child = spawn(cmd, args, { stdio: ["ignore", "pipe", "pipe"] });
    } catch (error) {
      finish(1);
      stderr += error instanceof Error ? error.message : String(error);
      return;
    }

    child.stdout.setEncoding("utf8");
    child.stderr.setEncoding("utf8");
    child.stdout.on("data", (chunk: string) => {
      stdout += chunk;
    });
    child.stderr.on("data", (chunk: string) => {
      stderr += chunk;
    });
    child.on("error", (error) => {
      stderr += error.message;
      finish(1);
    });
    child.on("close", (code) => {
      finish(code ?? 1);
    });
  });
}

import { existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join, resolve } from "node:path";
import { homedir } from "node:os";

/** Locate the package root from either dist/ or the TypeScript source tree. */
export function resolvePackageRoot(): string {
  let current = dirname(fileURLToPath(import.meta.url));

  while (true) {
    if (existsSync(join(current, "package.json"))) return current;
    const parent = dirname(current);
    if (parent === current) break;
    current = parent;
  }

  throw new Error(`Unable to locate pisquad package root from ${import.meta.url}`);
}

/** Resolve a path relative to the assets embedded in this package. */
export function resolveAsset(rel: string): string {
  return join(resolvePackageRoot(), "assets", rel);
}

/** Resolve an install target, expanding the conventional ~/ prefix. */
export function resolveTarget(input?: string, cwd = process.cwd()): string {
  const value = input ?? cwd;
  const expanded = value === "~" ? homedir() : value.startsWith("~/") ? join(homedir(), value.slice(2)) : value;
  return resolve(cwd, expanded);
}

/** Return the state file belonging to an install target. */
export function stateFile(target: string): string {
  return join(target, ".pi", ".pisquad", "state.json");
}

import pc from "picocolors";

let verbose = false;

export const logger = {
  setVerbose(value: boolean): void {
    verbose = value;
  },
  info(message: string): void {
    console.log(pc.cyan(message));
  },
  warn(message: string): void {
    console.warn(pc.yellow(message));
  },
  error(message: string): void {
    console.error(pc.red(message));
  },
  success(message: string): void {
    console.log(pc.green(message));
  },
  step(message: string): void {
    if (verbose) console.log(pc.dim(message));
  },
};

export const setVerbose = (value: boolean): void => logger.setVerbose(value);
export const info = (message: string): void => logger.info(message);
export const warn = (message: string): void => logger.warn(message);
export const error = (message: string): void => logger.error(message);
export const success = (message: string): void => logger.success(message);
export const step = (message: string): void => logger.step(message);

import { checkbox } from "@inquirer/prompts";
import { isInteractive } from "./env.js";

export type OptionalChannel = "codegraph" | "entire";

export interface Channels {
  core: true;
  codegraph: boolean;
  entire: boolean;
}

export interface ChannelDecisionOptions {
  all?: boolean;
  with?: string | string[];
  without?: string | string[];
  yes?: boolean;
  env?: NodeJS.ProcessEnv;
  target?: string;
}

const coreOnly: Channels = { core: true, codegraph: false, entire: false };

/** Ask only about optional channels; core is deliberately always selected. */
export async function promptChannels(_target?: string): Promise<Channels> {
  const selected = await checkbox<OptionalChannel>({
    message: "Select optional pi-squad channels",
    choices: [
      { name: "codegraph", value: "codegraph" },
      { name: "entire", value: "entire" },
    ],
  });

  return {
    core: true,
    codegraph: selected.includes("codegraph"),
    entire: selected.includes("entire"),
  };
}

function values(input: string | string[] | undefined): string[] {
  if (input === undefined) return [];
  const parts = Array.isArray(input) ? input : input.split(",");
  return parts.map((part) => part.trim().toLowerCase()).filter(Boolean);
}

function optionalChannels(input: string | string[] | undefined): Set<OptionalChannel> {
  const result = new Set<OptionalChannel>();
  for (const value of values(input)) {
    if (value === "codegraph" || value === "entire") result.add(value);
    else if (value !== "core") throw new Error(`Unknown channel: ${value}`);
  }
  return result;
}

function withChannels(channels: Set<OptionalChannel>): Channels {
  return {
    core: true,
    codegraph: channels.has("codegraph"),
    entire: channels.has("entire"),
  };
}

/**
 * Decide channels in the documented non-interactive precedence order.
 * Explicit flags win over environment variables; no tty always falls back to core.
 */
export async function decideChannels(opts: ChannelDecisionOptions = {}): Promise<Channels> {
  if (opts.all) return { core: true, codegraph: true, entire: true };

  const explicitWith = values(opts.with);
  if (explicitWith.length > 0) {
    return withChannels(optionalChannels(explicitWith));
  }

  const explicitWithout = values(opts.without);
  if (explicitWithout.length > 0) {
    const channels = optionalChannels(explicitWithout);
    return withChannels(new Set<OptionalChannel>());
  }

  if (opts.yes) return { ...coreOnly };

  const env = opts.env ?? process.env;
  const environmentWith = values(env.PISQUAD_WITH);
  if (environmentWith.length > 0) {
    return withChannels(optionalChannels(environmentWith));
  }

  const environmentWithout = values(env.PISQUAD_WITHOUT);
  if (environmentWithout.length > 0) {
    optionalChannels(environmentWithout);
    return { ...coreOnly };
  }

  if (isInteractive()) return promptChannels(opts.target);
  return { ...coreOnly };
}

import { readdirSync, readFileSync } from "node:fs";
import { resolveAsset } from "./paths.js";

/** List the top-level payload entries shipped in the npm package's assets/. */
export function listAssets(): string[] {
  return readdirSync(resolveAsset("."), { withFileTypes: true })
    .map((entry) => entry.name)
    .filter((name) => name !== "assets-version.txt")
    .sort();
}

/** Read the content snapshot version shipped with the assets. */
export function readAssetsVersion(): string {
  const versionFile = resolveAsset(".pi/assets-version.txt");
  let version: string;
  try {
    version = readFileSync(versionFile, "utf8").trim();
  } catch (error) {
    throw new Error(`Missing assets version file: ${versionFile}`, { cause: error });
  }
  if (!version) throw new Error(`Assets version file is empty: ${versionFile}`);
  return version;
}

import { copyFileSync, mkdirSync, readdirSync, statSync } from "node:fs";
import { dirname, join, relative } from "node:path";

export interface CopyOptions {
  filter?: (source: string, relativePath: string) => boolean;
  dryRun?: boolean;
}

/** Recursively copy a directory, optionally filtering entries or running as a preview. */
export function copyDir(src: string, dest: string, options: CopyOptions = {}): void {
  const copy = (sourceDir: string, destinationDir: string, relativeDir: string): void => {
    for (const entry of readdirSync(sourceDir)) {
      const source = join(sourceDir, entry);
      const entryRelativePath = relativeDir ? join(relativeDir, entry) : entry;
      if (options.filter && !options.filter(source, entryRelativePath)) continue;

      const destination = join(destinationDir, entry);
      if (statSync(source).isDirectory()) {
        if (!options.dryRun) mkdirSync(destination, { recursive: true });
        copy(source, destination, entryRelativePath);
      } else {
        if (options.dryRun) {
          console.log(`copy ${entryRelativePath}`);
        } else {
          mkdirSync(dirname(destination), { recursive: true });
          copyFileSync(source, destination);
        }
      }
    }
  };

  copy(src, dest, "");
}

import { existsSync, mkdirSync, readdirSync, renameSync, rmdirSync, unlinkSync, writeFileSync } from "node:fs";
import { dirname, join, basename } from "node:path";
import { randomBytes } from "node:crypto";

export function ensureDir(path: string): void {
  mkdirSync(path, { recursive: true });
}

export function pathExists(path: string): boolean {
  return existsSync(path);
}

/** Write a file through a same-directory temporary file and atomic rename. */
export function atomicWriteFile(path: string, content: string): void {
  ensureDir(dirname(path));
  const temporary = join(dirname(path), `.${basename(path)}.${process.pid}.${randomBytes(6).toString("hex")}.tmp`);
  try {
    writeFileSync(temporary, content, "utf8");
    renameSync(temporary, path);
  } catch (error) {
    try {
      unlinkSync(temporary);
    } catch {
      // Preserve the original write/rename failure.
    }
    throw error;
  }
}

/** Remove a directory only when it exists and is empty. */
export function removeIfEmpty(path: string): boolean {
  if (!existsSync(path)) return false;
  if (readdirSync(path).length !== 0) return false;
  try {
    rmdirSync(path);
    return true;
  } catch {
    return false;
  }
}

